class GymMember{protected String memberId;protected int monthlyFee;private int sessionsAttended;public GymMember(String id,int fee){if(id==null||id.trim().length()<4||fee<=0)throw new IllegalArgumentException("Invalid member details");memberId=id;monthlyFee=fee;}public void attendSession(){sessionsAttended++;}public int getSessionsAttended(){return sessionsAttended;}public String displayInfo(){return "Standard | Sessions: "+sessionsAttended;}}
class PremiumMember extends GymMember{private String trainerName;public PremiumMember(String id,int fee,String t){super(id,fee);trainerName=t;}public String getTrainerName(){return trainerName;}public String displayInfo(){return "Premium | Trainer: "+trainerName+" | Sessions: "+getSessionsAttended();}}
public class AttendanceAnnouncer{static String batchPrint(GymMember[] a){StringBuilder b=new StringBuilder();for(GymMember m:a){b.append(m.displayInfo());if(m instanceof PremiumMember)b.append(" [Trainer via downcast: ").append(((PremiumMember)m).getTrainerName()).append("]");b.append(" | ");}return b.toString();}public static void main(String[] args){GymMember a=new GymMember("MEM6",1000);PremiumMember p=new PremiumMember("MEM7",2000,"Coach Riya");System.out.println(batchPrint(new GymMember[]{a,p}));}}